#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);layers=%w[unit protocol ui e2e games];rows=layers.map do|layer|;dir=File.join(client,'tests',layer);files=Dir.glob(File.join(dir,'**/*')).select{|p|File.file?(p)};executables=files.reject{|p|%w[.md .txt].include?(File.extname(p).downcase)};{layer:layer,files:files.map{|p|p.delete_prefix(client+'/')},executableTests:executables.map{|p|p.delete_prefix(client+'/')},hasRunner:executables.any?};end;missing=rows.reject{|r|r[:hasRunner]}.map{|r|r[:layer]};report={schemaVersion:1,layers:rows,missingExecutableLayers:missing,coverageMappingPresent:false,passed:missing.empty?};out=File.join(root,'docs/generated/chyg06-test-layers.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG06 blocked: missing executable tests for #{missing.join(', ')} and no coverage map" unless report[:passed]
